"""Calibration loss functions, convergence trace, information criteria, out-of-sample validation, stability and the multi-criterion scorecard, on quotes generated by a known model."""

from __future__ import annotations

import numpy as np
import pytest

from src.derivatives import calibration as cal
from src.derivatives import levy
from src.derivatives import model_validation as mv

TRUE = {"sigma": 0.18, "lam": 0.6, "mu_j": -0.12, "sigma_j": 0.10}


def make_quotes(params=None, noise=0.0, seed=0, spread=0.004, T=(0.1, 0.25, 0.5, 1.0)) -> cal.Quotes:
    rng = np.random.default_rng(seed)
    S, r, q = 100.0, 0.02, 0.0
    ts, ks = [], []
    for t in T:
        F = S * np.exp((r - q) * t)
        for k in np.linspace(-0.25, 0.25, 11):
            ts.append(t)
            ks.append(float(F * np.exp(k)))
    shell = cal.Quotes(S, r, q, ts, ks, np.full(len(ts), 0.2))
    model = levy.Merton(**(params or TRUE))
    iv = cal.model_ivs(model, shell) + noise * rng.normal(size=len(ts))
    return cal.Quotes(S, r, q, ts, ks, iv, bid_iv=iv - spread, ask_iv=iv + spread)


@pytest.fixture(scope="module")
def quotes():
    return make_quotes()


def test_the_true_model_is_recovered_with_a_trace_of_the_optimiser_and_an_information_criterion(quotes):
    fit = cal.calibrate("merton", quotes, n_starts=2, max_nfev=200)
    assert fit.rmse < 2e-3 and fit.n_params == 4 and np.isfinite(fit.bic) and fit.residuals is not None and len(fit.residuals) == len(quotes.T)
    assert len(fit.trace) >= 2 and all(b2 <= b1 + 1e-15 for (_, b1), (_, b2) in zip(fit.trace, fit.trace[1:])), "the best cost never rises"
    assert fit.summary()["trace"] and fit.summary()["loss"] == "iv" and fit.summary()["n_params"] == 4


def test_the_band_loss_does_not_penalise_a_model_volatility_inside_the_markets_bid_ask(quotes):
    wide = cal.Quotes(quotes.S, quotes.r, quotes.q, quotes.T, quotes.K, quotes.iv, bid_iv=quotes.iv - 0.05, ask_iv=quotes.iv + 0.05)
    fit = cal.calibrate("merton", wide, loss="band", n_starts=1, max_nfev=40)
    assert fit.loss == "band" and fit.within_band == pytest.approx(1.0, abs=0.2) and fit.trace[-1][1] < 1e-6, "everything is inside a five-point band: nothing left to fit"
    with pytest.raises(ValueError, match="needs the bid and ask"):
        cal.calibrate("merton", cal.Quotes(quotes.S, quotes.r, quotes.q, quotes.T, quotes.K, quotes.iv), loss="band")
    with pytest.raises(ValueError, match="loss is"):
        cal.calibrate("merton", quotes, loss="nope")
    v = cal.calibrate("merton", quotes, loss="vega", n_starts=1, max_nfev=60)
    assert v.loss == "vega" and v.rmse < 0.01


def test_out_of_sample_error_is_measured_on_held_out_quotes_for_both_split_modes(quotes):
    train, test = mv.split(quotes, "strikes", 0.25, seed=1)
    assert len(train.T) + len(test.T) == len(quotes.T) and set(test.K).isdisjoint(set(train.K)) and test.K.min() > quotes.K.min()
    o = mv.out_of_sample("merton", quotes, "strikes", seed=1, n_starts=1, max_nfev=80)
    assert o["out_of_sample_rmse"] < 0.01 and o["n_test"] == len(test.T)
    e = mv.out_of_sample("merton", quotes, "expiry", n_starts=1, max_nfev=80)
    assert e["n_test"] == 11 and e["out_of_sample_rmse"] < 0.02, "the longest expiry was never fitted"
    with pytest.raises(ValueError, match="mode is"):
        mv.split(quotes, "random")


def test_a_wrong_model_does_worse_out_of_sample_than_the_true_one(quotes):
    right = mv.out_of_sample("merton", quotes, "expiry", n_starts=1, max_nfev=80)
    wrong = mv.out_of_sample("heston", quotes, "expiry", n_starts=1, max_nfev=80)
    assert right["out_of_sample_rmse"] < wrong["out_of_sample_rmse"] * 1.5 or right["out_of_sample_rmse"] < 0.005


def test_parameter_stability_over_dated_calibrations_is_measured_and_an_unstable_set_is_called_so():
    steady = [make_quotes({**TRUE, "sigma": 0.18 + 0.001 * i}, seed=i) for i in range(4)]
    s = mv.stability("merton", steady, dates=["2026-01-0%d" % (i + 1) for i in range(4)], n_starts=1, max_nfev=60)
    assert len(s["rows"]) == 4 and s["rows"][0]["date"] == "2026-01-01" and s["mean_instability"] < 0.9 and set(s["parameter_instability"]) == set(TRUE)
    with pytest.raises(ValueError, match="at least three"):
        mv.stability("merton", steady[:2])


def test_the_residual_grid_shows_structure_by_expiry_and_moneyness(quotes):
    bad = cal.calibrate("merton", quotes, fixed={"lam": 0.01}, n_starts=1, max_nfev=40)                 # almost no jumps: the smile is not reproduced
    g = mv.residual_grid(bad, quotes, bins=5)
    arr = np.array([[np.nan if v is None else v for v in row] for row in g["error"]])
    assert arr.shape == (4, 5) and g["unit"].startswith("volatility") and np.nanmax(np.abs(arr)) > 0.003 and sum(sum(r) for r in g["count"]) == len(quotes.T)


def test_the_scorecard_ranks_on_several_criteria_and_says_when_in_sample_fit_misleads(quotes):
    sc = mv.scorecard(quotes, models=("merton", "vg"), n_starts=1, max_nfev=60)
    assert [r["model"] for r in sc["models"]] == ["merton", "vg"] and set(sc["ranks"]) == {"in_sample_rmse", "out_of_sample_rmse", "bic", "seconds"}
    assert sc["preferred_by_combined_rank"] in ("merton", "vg") and all(r["n_params"] > 0 and r["out_of_sample_rmse"] is not None for r in sc["models"])
    assert "single chain" in sc["caveat"].lower() and sc["validation"]["mode"] == "strikes"
